import { cn } from "@/lib/utils"

/** Round initials mark (the library has no Avatar primitive yet). */
export function Avatar({ name, size = "default", className }: { name: string; size?: "sm" | "default" | "lg"; className?: string }) {
  const initials = name
    .split(/\s+/)
    .map((p) => p[0])
    .slice(0, 2)
    .join("")
    .toUpperCase()
  return (
    <span
      aria-hidden
      className={cn(
        "inline-grid shrink-0 place-items-center rounded-full bg-linear-to-b from-primary/20 to-primary/8 font-semibold text-primary shadow-raised",
        size === "sm" && "size-6 text-xs",
        size === "default" && "size-9 text-sm",
        size === "lg" && "size-16 text-xl",
        className
      )}
    >
      {initials}
    </span>
  )
}

import { cn } from "@/lib/utils"

/*
 * Generated cover artwork in CSS, so posts need no image files. Every colour
 * is a theme token, so the art follows light and dark. Four compositions.
 * Standalone covers add the image outline (outline-black/10, dark:outline-white/10).
 */
export function CoverArt({ variant, className }: { variant: 0 | 1 | 2 | 3; className?: string }) {
  return (
    <div
      role="img"
      aria-label="Abstract cover illustration"
      className={cn(
        "relative isolate overflow-hidden bg-linear-to-br from-primary/18 via-muted to-background dark:from-primary/25",
        className
      )}
    >
      {variant === 0 && (
        // Nested rounded squares, drawn concentric: 32 = 16 + 16, 16 = 10 + 6.
        <div className="absolute inset-0 grid place-items-center">
          <div className="grid size-3/5 max-w-72 place-items-center rounded-4xl bg-card/70 p-4 shadow-surface">
            <div className="grid size-full place-items-center rounded-xl bg-primary/14 p-1.5 shadow-well">
              <div className="size-full rounded-md bg-primary shadow-primary" />
            </div>
          </div>
        </div>
      )}
      {variant === 1 && (
        // Staggered pills easing in.
        <div className="absolute inset-0 flex flex-col justify-center gap-3 px-12">
          {[90, 72, 56, 40].map((w, i) => (
            <div
              key={w}
              className={cn(
                "h-6 rounded-full shadow-raised",
                i === 0 ? "w-11/12 bg-primary" : i === 1 ? "w-9/12 bg-primary/60" : i === 2 ? "w-7/12 bg-primary/35" : "w-5/12 bg-card"
              )}
            />
          ))}
        </div>
      )}
      {variant === 2 && (
        // A lightness ramp of one hue.
        <div className="absolute inset-0 flex items-end gap-2 px-10 pb-10">
          {["h-1/5 bg-primary/10", "h-2/5 bg-primary/25", "h-3/5 bg-primary/45", "h-4/5 bg-primary/70", "h-11/12 bg-primary", "h-3/4 bg-foreground/80"].map((c) => (
            <div key={c} className={cn("flex-1 rounded-xl shadow-raised", c)} />
          ))}
        </div>
      )}
      {variant === 3 && (
        // Fixed-width digits.
        <div className="absolute inset-0 grid place-items-center">
          <div className="flex gap-2 font-mono text-5xl font-semibold text-primary tabular-nums sm:text-6xl">
            {["1", "0", "4", "8"].map((d, i) => (
              <span key={i} className="grid h-20 w-14 place-items-center rounded-2xl bg-card/80 shadow-raised sm:h-24 sm:w-16">
                {d}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

"use client"

import * as React from "react"
import { motion, useReducedMotion, type Variants } from "motion/react"

/*
 * Staged entrance for a hero or page header: children marked <StaggerItem>
 * enter 100ms apart with opacity, 4px blur and 12px rise over 300ms ease-out.
 * Under reduced motion they only cross-fade.
 */

const item: Variants = {
  hidden: { opacity: 0, y: 12, filter: "blur(4px)" },
  visible: { opacity: 1, y: 0, filter: "blur(0px)", transition: { duration: 0.3, ease: "easeOut" } },
}
const fade: Variants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { duration: 0.3, ease: "easeOut" } },
}

const ReduceContext = React.createContext(false)

export function Stagger({ delay = 0, className, children }: { delay?: number; className?: string; children: React.ReactNode }) {
  const reduce = useReducedMotion() ?? false
  return (
    <ReduceContext.Provider value={reduce}>
      <motion.div
        className={className}
        initial="hidden"
        animate="visible"
        variants={{ visible: { transition: { staggerChildren: 0.1, delayChildren: delay } } }}
      >
        {children}
      </motion.div>
    </ReduceContext.Provider>
  )
}

export function StaggerItem({ className, children }: { className?: string; children: React.ReactNode }) {
  const reduce = React.useContext(ReduceContext)
  return (
    <motion.div className={className} variants={reduce ? fade : item}>
      {children}
    </motion.div>
  )
}

"use client"

import * as React from "react"
import { motion, useReducedMotion } from "motion/react"

import { cn } from "@/lib/utils"

export type TocItem = { id: string; title: string; depth: 2 | 3 }

/** Tracks which heading is currently being read: the last one above the top 30% of the viewport. */
export function useScrollSpy(ids: string[], offset = 0.3) {
  const [active, setActive] = React.useState(ids[0] ?? "")
  React.useEffect(() => {
    const els = ids.map((id) => document.getElementById(id)).filter((el): el is HTMLElement => !!el)
    if (!els.length) return
    let frame = 0
    const update = () => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(() => {
        const line = window.innerHeight * offset
        let current = els[0].id
        for (const el of els) if (el.getBoundingClientRect().top <= line) current = el.id
        // At the very bottom, the last heading wins even if it never reaches the line.
        if (window.innerHeight + window.scrollY >= document.documentElement.scrollHeight - 2) current = els[els.length - 1].id
        setActive(current)
      })
    }
    update()
    window.addEventListener("scroll", update, { passive: true })
    window.addEventListener("resize", update)
    return () => {
      cancelAnimationFrame(frame)
      window.removeEventListener("scroll", update)
      window.removeEventListener("resize", update)
    }
  }, [ids, offset])
  return active
}

export function TableOfContents({ items }: { items: TocItem[] }) {
  const ids = React.useMemo(() => items.map((i) => i.id), [items])
  const active = useScrollSpy(ids)
  const reduce = useReducedMotion()
  return (
    <nav aria-label="On this page" className="flex flex-col gap-3">
      <h2 className="text-xs font-medium tracking-wider text-muted-foreground uppercase">On this page</h2>
      <ul className="relative flex flex-col border-s border-border">
        {items.map((item) => {
          const isActive = item.id === active
          return (
            <li key={item.id} className="relative">
              {isActive && (
                <motion.span
                  layoutId="toc-indicator"
                  aria-hidden
                  className="absolute inset-y-1 -start-px w-0.5 rounded-full bg-primary"
                  transition={reduce ? { duration: 0 } : { type: "spring", duration: 0.35, bounce: 0 }}
                />
              )}
              <a
                href={`#${item.id}`}
                aria-current={isActive ? "location" : undefined}
                className={cn(
                  "block py-1.5 text-sm text-pretty transition-colors duration-150 outline-none hover:text-foreground focus-visible:text-foreground focus-visible:underline",
                  item.depth === 3 ? "ps-7" : "ps-4",
                  isActive ? "font-medium text-foreground" : "text-muted-foreground"
                )}
              >
                {item.title}
              </a>
            </li>
          )
        })}
      </ul>
    </nav>
  )
}

